import sys

def main() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))          # registered voters
    C = int(next(it))          # candidates
    V = int(next(it))          # number of votes
    out_lines = []
    for i in range(V):
        # if we already have N valid votes, any further vote is invalid
        if i >= N:
            out_lines.append("INVALID")
            continue
        try:
            vote = int(next(it))
        except StopIteration:
            break
        if 1 <= vote <= C:
            out_lines.append("VALID")
        else:
            out_lines.append("INVALID")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
